package com.xiaoxiao.pet;
import android.app.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;

/** Deleting a row never dismisses this panel or its parent role-management page. */
final class ClonePanel {
 final MainActivity activity;final PetService service;final String role;final LinearLayout rows;final ScrollView scroll;final TextView count;AlertDialog dialog;
 ClonePanel(MainActivity a,String role){activity=a;service=PetService.instance;this.role=role;LinearLayout content=a.column();content.setPadding(a.dp(16),0,a.dp(16),a.dp(8));count=a.text("",13);count.setTextColor(Apple.SECONDARY);count.setPadding(0,a.dp(6),0,a.dp(12));content.addView(count);scroll=new SpringScrollView(a);rows=a.column();scroll.addView(rows);content.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(a.dp(380),a.getResources().getDisplayMetrics().heightPixels/2)));a.button(content,"添加分身（最多8个）",v->{service.cloneRole(role);refresh();});dialog=new Apple.Builder(a).setTitle(Data.name(role)+" · 分身").setView(content).setNegativeButton("关闭",null).create();refresh();}
 void show(){dialog.show();Apple.dialog(dialog);dialog.getButton(-2).setTextColor(Apple.BLUE);}
 ArrayList<PetService.Pet> clones(){ArrayList<PetService.Pet> found=new ArrayList<>();for(PetService.Pet p:service.pets.values())if(p.role.equals(role)&&!p.id.equals(role))found.add(p);return found;}
 void status(){int n=clones().size();count.setText(n+" / 8 个分身 · 删除后保留在此列表");if(n==0){rows.removeAllViews();TextView empty=activity.text("还没有分身",16);empty.setTextColor(Apple.SECONDARY);empty.setGravity(Gravity.CENTER);empty.setPadding(0,activity.dp(32),0,activity.dp(32));rows.addView(empty);}}
 void refresh(){int y=scroll.getScrollY();rows.removeAllViews();for(PetService.Pet p:clones())row(p);status();scroll.post(()->scroll.scrollTo(0,y));}
 void row(PetService.Pet p){LinearLayout row=activity.column();row.setPadding(0,activity.dp(10),0,activity.dp(12));TextView heading=activity.text("分身 "+p.id.substring(p.id.indexOf('#')+1),17);row.addView(heading);LinearLayout controls=new LinearLayout(activity);controls.setPadding(0,activity.dp(10),0,0);String[] labels={p.visible?"隐藏":"显示","资料","大小","删除"};for(int i=0;i<labels.length;i++){final int index=i;Button b=new Button(activity);b.setText(labels[i]);Apple.button(b,false);b.setTextSize(13);b.setPadding(activity.dp(4),0,activity.dp(4),0);LinearLayout.LayoutParams cell=new LinearLayout.LayoutParams(0,activity.dp(44),1);if(i>0)cell.leftMargin=activity.dp(6);controls.addView(b,cell);if(i==3)b.setTextColor(Apple.DANGER);b.setOnClickListener(v->{if(!service.pets.containsKey(p.id))return;if(index==0){if(p.visible)p.hide();else{p.visible=true;p.attach();service.control(MainActivity.active);}service.save();b.setText(p.visible?"隐藏":"显示");}if(index==1)ProfilePage.show(activity,role);if(index==2)activity.size(p);if(index==3){service.remove(p.id);rows.removeView(row);status();}});}row.addView(controls);View line=new View(activity);line.setBackgroundColor(Apple.LINE);LinearLayout.LayoutParams divider=new LinearLayout.LayoutParams(-1,activity.dp(1));divider.topMargin=activity.dp(12);row.addView(line,divider);rows.addView(row);}
}
